'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import type { Lang } from '@/lib/data'
import { SPEECH_LOCALE } from '@/lib/assistant'

export type VoiceSearchError =
  | 'unsupported'
  | 'permission-denied'
  | 'no-speech'
  | 'failed'

// Minimal typings for the Web Speech API (not in standard lib.dom types)
type SpeechRecognitionResultLike = {
  0: { transcript: string }
  isFinal: boolean
}
type SpeechRecognitionEventLike = {
  resultIndex: number
  results: { length: number; [i: number]: SpeechRecognitionResultLike }
}
type SpeechRecognitionLike = {
  lang: string
  continuous: boolean
  interimResults: boolean
  maxAlternatives?: number
  start: () => void
  stop: () => void
  abort: () => void
  onresult: ((e: SpeechRecognitionEventLike) => void) | null
  onend: (() => void) | null
  onerror: ((e: { error?: string }) => void) | null
}

function getRecognitionCtor(): (new () => SpeechRecognitionLike) | null {
  if (typeof window === 'undefined') return null
  const w = window as unknown as {
    SpeechRecognition?: new () => SpeechRecognitionLike
    webkitSpeechRecognition?: new () => SpeechRecognitionLike
  }
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null
}

/**
 * YouTube-style voice search.
 *
 * - Recognition language follows the selected UI language (en-IN / hi-IN / mr-IN).
 * - Live interim transcript is exposed so the input can be filled as the user speaks.
 * - Distinct error states: unsupported browser, microphone permission denied,
 *   no speech detected, generic failure.
 * - Starting a new session aborts any in-progress one (toggle behaviour).
 */
export function useVoiceSearch(lang: Lang) {
  const [supported, setSupported] = useState(true)
  const [listening, setListening] = useState(false)
  const [interim, setInterim] = useState('')
  const [error, setError] = useState<VoiceSearchError | null>(null)

  const recognitionRef = useRef<SpeechRecognitionLike | null>(null)
  const finalRef = useRef('')
  const onFinalRef = useRef<((text: string) => void) | null>(null)

  useEffect(() => {
    setSupported(Boolean(getRecognitionCtor()))
    return () => {
      try {
        recognitionRef.current?.abort()
      } catch {
        /* noop */
      }
    }
  }, [])

  const stop = useCallback(() => {
    try {
      recognitionRef.current?.stop()
    } catch {
      /* noop */
    }
    setListening(false)
  }, [])

  const resetError = useCallback(() => setError(null), [])

  const start = useCallback(
    (onFinal?: (text: string) => void) => {
      const Ctor = getRecognitionCtor()
      if (!Ctor) {
        setSupported(false)
        setError('unsupported')
        return
      }
      // Abort any previous session so we always listen fresh.
      try {
        recognitionRef.current?.abort()
      } catch {
        /* noop */
      }
      try {
        window.speechSynthesis?.cancel()
      } catch {
        /* noop */
      }

      const recognition = new Ctor()
      recognition.lang = SPEECH_LOCALE[lang]
      recognition.continuous = false
      recognition.interimResults = true
      recognition.maxAlternatives = 1
      finalRef.current = ''
      onFinalRef.current = onFinal ?? null
      setError(null)
      setInterim('')

      recognition.onresult = (e) => {
        let interimText = ''
        let finalText = ''
        for (let i = e.resultIndex; i < e.results.length; i++) {
          const res = e.results[i]
          if (res.isFinal) finalText += res[0].transcript
          else interimText += res[0].transcript
        }
        if (finalText) finalRef.current += finalText
        setInterim((finalRef.current + interimText).trim())
      }

      recognition.onerror = (e) => {
        const code = e?.error
        if (code === 'not-allowed' || code === 'service-not-allowed') {
          setError('permission-denied')
        } else if (code === 'no-speech' || code === 'audio-capture') {
          setError('no-speech')
        } else if (code === 'aborted') {
          // Manual stop — not an error.
        } else {
          setError('failed')
        }
        setListening(false)
      }

      recognition.onend = () => {
        setListening(false)
        const result = finalRef.current.trim()
        if (result) {
          setInterim('')
          if (onFinalRef.current) onFinalRef.current(result)
        }
      }

      recognitionRef.current = recognition
      try {
        recognition.start()
        setListening(true)
      } catch {
        setError('failed')
        setListening(false)
      }
    },
    [lang],
  )

  return { supported, listening, interim, error, start, stop, resetError }
}
